insert into public.personas (account_id, id, name, description, accent, icon) values
  ('acc_northwind', 'pe-technician', 'Maintenance Technician', 'Hands-on on the shop floor. Executes work orders, logs findings, and needs fast mobile access between jobs.', 'blue', 'Wrench'),
  ('acc_northwind', 'pe-planner', 'Maintenance Planner', 'Schedules preventive and corrective work, balances technician capacity, and keeps the backlog under control.', 'indigo', 'CalendarClock'),
  ('acc_northwind', 'pe-manager', 'Maintenance Manager', 'Owns team performance and maintenance KPIs. Lives in dashboards and reports to operations leadership.', 'violet', 'HardHat'),
  ('acc_northwind', 'pe-reliability', 'Reliability Engineer', 'Analyzes failure patterns, drives RCA, and optimizes maintenance strategy from asset history data.', 'teal', 'Gauge'),
  ('acc_northwind', 'pe-warehouse', 'Warehouse Employee', 'Manages spare parts stock, issues materials to work orders, and handles goods receipt.', 'amber', 'Warehouse'),
  ('acc_northwind', 'pe-purchaser', 'Purchaser', 'Converts requisitions to orders, manages suppliers, and tracks delivery of critical parts.', 'orange', 'ShoppingCart'),
  ('acc_northwind', 'pe-operations', 'Operations Manager', 'Owns plant uptime. Cares about how maintenance impacts production throughput and safety.', 'green', 'Factory'),
  ('acc_northwind', 'pe-asset', 'Asset Manager', 'Manages the asset register and lifecycle, capital planning, and long-term replacement strategy.', 'cyan', 'Boxes'),
  ('acc_northwind', 'pe-admin', 'Administrator', 'Configures the system, manages users and permissions, and maintains master data quality.', 'slate', 'ShieldCheck'),
  ('acc_northwind', 'pe-executive', 'Executive', 'C-level sponsor. Wants evidence that maintenance investments reduce risk and cost.', 'purple', 'Briefcase'),
  ('acc_northwind', 'pe-it', 'IT Manager', 'Responsible for integrations, security, SSO, and how the platform fits the enterprise landscape.', 'rose', 'Server')
