  ('acc_northwind', 'hl-l2', 'tr-lukas', 's-l6', 0, 80, 'I take a photo of the nameplate because searching for the asset takes longer than the repair itself', 'pain-point', 'Asset search slower than repair', array['tag-search']::text[], 'u-sanne', 'in-search-global'),
  ('acc_northwind', 'hl-l3', 'tr-lukas', 's-l8', 0, 70, 'I never really know if my update actually saved when the signal is weak', 'insight', 'Sync distrust → screenshot workaround', array['tag-mobile-experience']::text[], 'u-sanne', 'in-mobile-offline-trust'),
  ('acc_northwind', 'hl-l4', 'tr-lukas', 's-l10', 0, 40, 'That would be huge. As long as I can see clearly that it will sync', 'opportunity', 'Offline-first with visible sync state', array['tag-mobile-experience']::text[], 'u-sanne', null),
  ('acc_northwind', 'hl-f1', 'tr-fatima', 's-f4', 0, 70, 'I rebuild the same filter every morning because it never remembers what I was looking at', 'pain-point', 'Filters don''t persist', array['tag-planning','tag-usability']::text[], 'u-tom', 'in-search-recent'),
  ('acc_northwind', 'hl-f2', 'tr-fatima', 's-f6', 0, 90, 'One machine breakdown and I''m dragging thirty jobs around the board by hand for the rest of the morning', 'pain-point', 'Rescheduling cascade', array['tag-planning','tag-work-orders']::text[], 'u-tom', 'in-plan-replan-cost'),
